<?php require_once __DIR__.'/../functions.php'; init_db(); require_login();$s=one('SELECT * FROM settings WHERE id=1');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$hero=save_upload('hero_upload');$logo=save_upload('logo_upload');$fields=['site_title','intro','phone','email','address','facebook','instagram','vimeo','youtube','impressum','privacy'];$set=[];$vals=[];foreach($fields as $f){$set[]="$f=?";$vals[]=trim((string)($_POST[$f]??''));}if($hero){$set[]='hero_image=?';$vals[]=$hero;}if($logo){$set[]='logo=?';$vals[]=$logo;}$vals[] = 1;db()->prepare('UPDATE settings SET '.implode(',',$set).' WHERE id=?')->execute($vals);flash('Einstellungen gespeichert.');redirect('settings.php');}catch(Throwable $e){$err=$e->getMessage();}}$s=one('SELECT * FROM settings WHERE id=1');$flash=flash();?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Einstellungen – Young Images</title><link rel="stylesheet" href="../css/admin.css"></head><body><div class="admin-shell"><aside><img src="../assets/young-images-logo.png" class="admin-logo"><nav><a href="index.php">Dashboard</a><a href="media.php">Medien / Upload</a><a class="sel" href="settings.php">Einstellungen</a><a href="../index.php" target="_blank">Website ansehen ↗</a><a href="logout.php">Abmelden</a></nav></aside><main class="admin-main"><div class="admin-head"><div><div class="eyebrow">GRUNDLAGEN</div><h1>Einstellungen</h1></div></div><?php if($flash):?><div class="success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><section class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="two"><label>Seitentitel<input name="site_title" value="<?=e($s['site_title'])?>"></label><label>E-Mail<input name="email" value="<?=e($s['email'])?>"></label><label>Telefon<input name="phone" value="<?=e($s['phone'])?>"></label><label>Adresse<textarea name="address" rows="3"><?=e($s['address'])?></textarea></label></div><label>Intro<textarea name="intro" rows="3"><?=e($s['intro'])?></textarea></label><div class="two"><label>Instagram URL<input name="instagram" value="<?=e($s['instagram'])?>"></label><label>Vimeo URL<input name="vimeo" value="<?=e($s['vimeo'])?>"></label><label>Facebook URL<input name="facebook" value="<?=e($s['facebook'])?>"></label><label>YouTube URL<input name="youtube" value="<?=e($s['youtube'])?>"></label></div><label>Impressum<textarea name="impressum" rows="6"><?=e($s['impressum'])?></textarea></label><label>Datenschutz<textarea name="privacy" rows="6"><?=e($s['privacy'])?></textarea></label><div class="two"><label>Logo ersetzen<input type="file" name="logo_upload" accept="image/*"><small>Aktuell: <?=e($s['logo'])?></small></label><label>Hero-Bild ersetzen<input type="file" name="hero_upload" accept="image/*"><small>Aktuell: <?=e($s['hero_image'])?></small></label></div><button>Speichern</button></form></section></main></div></body></html>
